create table if not exists chlom_runtime.construction_work_queue (
  work_id text primary key,
  workstream text not null,
  canonical_name text not null,
  scope_type text not null check (scope_type in ('protocol','module','platform','binding','agent','algorithm','oracle','release','paper')),
  scope_id text not null,
  priority integer not null check(priority between 1 and 999),
  owner_agent_id text not null references chlom_runtime.agent_templates(agent_id) on delete restrict,
  verifier_agent_id text not null references chlom_runtime.agent_templates(agent_id) on delete restrict,
  depends_on text[] not null default '{}',
  closes_gates text[] not null default '{}',
  required_outputs jsonb not null default '{}'::jsonb,
  state text not null default 'ready' check(state in ('ready','running','waiting','blocked','verifying','done','superseded')),
  blocker_reason text,
  evidence jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check(owner_agent_id <> verifier_agent_id)
);
create index if not exists idx_chlom_work_queue_state_priority on chlom_runtime.construction_work_queue(state,priority,work_id);
revoke all on chlom_runtime.construction_work_queue from public,anon,authenticated;

