on conflict (work_id) do update set
 workstream=excluded.workstream,canonical_name=excluded.canonical_name,scope_type=excluded.scope_type,scope_id=excluded.scope_id,
 priority=excluded.priority,owner_agent_id=excluded.owner_agent_id,verifier_agent_id=excluded.verifier_agent_id,depends_on=excluded.depends_on,
 closes_gates=excluded.closes_gates,required_outputs=excluded.required_outputs,
 state=case when chlom_runtime.construction_work_queue.state='done' then 'done' else excluded.state end,
 updated_at=now();

create or replace function public.chlom_construction_work_queue_snapshot()
returns jsonb language sql stable security definer set search_path to 'pg_catalog','chlom_runtime'
as $$
select jsonb_build_object('work',coalesce(jsonb_agg(jsonb_build_object(
 'work_id',work_id,'workstream',workstream,'canonical_name',canonical_name,'scope_type',scope_type,'scope_id',scope_id,
 'priority',priority,'owner_agent_id',owner_agent_id,'verifier_agent_id',verifier_agent_id,'depends_on',depends_on,
 'closes_gates',closes_gates,'required_outputs',required_outputs,'state',state,'blocker_reason',blocker_reason,'updated_at',updated_at
) order by priority,work_id),'[]'::jsonb),'generated_at',now()) from chlom_runtime.construction_work_queue where state <> 'superseded'
$$;
revoke all on function public.chlom_construction_work_queue_snapshot() from public,anon,authenticated;
grant execute on function public.chlom_construction_work_queue_snapshot() to service_role;

insert into integration_control.mcp_tools(tool_name,service_id,operation_key,risk_class,enabled,requires_human_approval,input_schema,output_schema,notes)
values('chlom.build.queue','chlom_core','build.queue','D0',true,false,'{"type":"object","additionalProperties":false}'::jsonb,'{"type":"object"}'::jsonb,'Read the CHLOM machine construction queue, dependencies, gate targets and assigned independent owner/verifier agents.')
on conflict(tool_name) do update set service_id=excluded.service_id,operation_key=excluded.operation_key,risk_class=excluded.risk_class,enabled=true,requires_human_approval=false,input_schema=excluded.input_schema,output_schema=excluded.output_schema,notes=excluded.notes,updated_at=now();
